/* Auto-scrolling recommendation wall.
   Each column holds two identical sets so translateY(-50%) loops seamlessly.
   Cards carry their own bottom margin (not a column gap) so half the track
   height is exactly one set — otherwise the loop jumps by half a gap. */
function recWall(){
  const COLS = [[],[],[]];
  RECS.forEach((r,i)=>COLS[i % 3].push(r));
  const DUR = ['64s','78s','70s'];

  const set = (col,hidden) => `
    <div class="wall-set"${hidden?' aria-hidden="true"':''}>
      ${col.map(r=>`
        <figure class="tcard wall-card">
          <span class="tcard-top">
          <span class="tcard-mark">${I.quote}</span>
          <span class="li-badge" title="Sourced from LinkedIn">${I.linkedin}<span>LinkedIn recommendation</span></span>
        </span>
          <blockquote>${r.quote}</blockquote>
          <figcaption>
            <span class="tcard-name">${r.name}</span>
            <span class="tcard-role">${r.role}</span>
            <span class="tcard-meta"><span class="tcard-rel">${r.rel}</span> · ${r.date}</span>
          </figcaption>
        </figure>`).join('')}
    </div>`;

  return `
  <div class="wall rv" id="wall" role="region" aria-label="Recommendations">
    ${COLS.map((col,i)=>`
      <div class="wall-col" style="--dur:${DUR[i]}">
        ${set(col,false)}
        ${set(col,true)}
      </div>`).join('')}
  </div>
`;
}

function recCard(r,i){
  return `
  <figure class="tcard rv" style="--i:${Math.min(i,3)}">
    <span class="tcard-top">
          <span class="tcard-mark">${I.quote}</span>
          <span class="li-badge" title="Sourced from LinkedIn">${I.linkedin}<span>LinkedIn recommendation</span></span>
        </span>
    <blockquote>${r.quote}</blockquote>
    <figcaption>
      <span class="tcard-name">${r.name}</span>
      <span class="tcard-role">${r.role}</span>
      <span class="tcard-meta"><span class="tcard-rel">${r.rel}</span> · ${r.date}</span>
    </figcaption>
  </figure>`;
}

