/* ---------- Sandwich leave ---------- */
function initLeave(){
  const cal = document.getElementById('cal');
  if(!cal) return;

  // April 2026: 1st is a Wednesday. Grid starts Monday.
  const DAYS = ['M','T','W','T','F','S','S'];
  const START_OFFSET = 2;      // Wed
  const DAYS_IN_MONTH = 30;
  const LEAVE = {
    casual: {label:'Casual leave', total:15, used:7, sandwich:true},
    earned: {label:'Earned leave', total:21, used:9, sandwich:false},
    sick:   {label:'Sick leave',   total:6,  used:4, sandwich:false}
  };
  let type = 'casual';
  let selected = new Set();

  function dow(d){ return (START_OFFSET + d - 1) % 7; }        // 0=Mon..6=Sun
  function isWeekend(d){ const w = dow(d); return w === 5 || w === 6; }

  // Sandwich days = weekend days strictly between two selected working days
  function sandwichDays(){
    if(!LEAVE[type].sandwich) return [];
    const sel = [...selected].sort((a,b)=>a-b);
    if(sel.length < 2) return [];
    const out = new Set();
    for(let i=0;i<sel.length-1;i++){
      const a = sel[i], b = sel[i+1];
      const between = [];
      let allWeekend = b - a > 1;
      for(let d=a+1; d<b; d++){
        if(!isWeekend(d)){ allWeekend = false; break; }
        between.push(d);
      }
      if(allWeekend && between.length) between.forEach(d=>out.add(d));
    }
    return [...out];
  }

  function render(){
    const sw = sandwichDays();
    const swSet = new Set(sw);
    let html = DAYS.map(d=>`<div class="cal-h">${d}</div>`).join('');
    for(let i=0;i<START_OFFSET;i++) html += `<div></div>`;
    for(let d=1; d<=DAYS_IN_MONTH; d++){
      const cls = ['day'];
      if(isWeekend(d)) cls.push('we');
      if(selected.has(d)) cls.push('sel');
      else if(swSet.has(d)) cls.push('sw');
      const label = `${d} April${selected.has(d)?', selected':''}${swSet.has(d)?', counted as sandwich leave':''}`;
      html += `<button class="${cls.join(' ')}" data-d="${d}" aria-label="${label}" aria-pressed="${selected.has(d)}">${d}</button>`;
    }
    cal.innerHTML = html;

    const total = selected.size + sw.length;
    const n = document.getElementById('tally-n');
    n.textContent = total;
    n.classList.toggle('warn', sw.length > 0);
    document.getElementById('tally-l').textContent =
      total === 1 ? 'day deducted' : 'days deducted';

    const alert = document.getElementById('sw-alert');
    if(sw.length){
      alert.classList.remove('hide');
      document.getElementById('sw-detail').textContent =
        `${sw.length} weekend ${sw.length===1?'day':'days'} between your selected dates ${sw.length===1?'is':'are'} also deducted — ${selected.size} selected + ${sw.length} sandwich = ${total} days.`;
    } else {
      alert.classList.add('hide');
    }

    // balances
    const bal = document.getElementById('bal');
    bal.innerHTML = Object.entries(LEAVE).map(([k,v])=>{
      const deduct = k === type ? total : 0;
      const used = Math.min(v.total, v.used + deduct);
      const pct = (used / v.total) * 100;
      const over = v.used + deduct > v.total;
      return `<div class="bal-r">
        <span class="nm">${v.label}</span>
        <span class="bal-tr"><span class="bal-f" style="width:${pct}%;background:${over?'var(--danger)':deduct?'var(--ac)':'var(--fg-3)'}"></span></span>
        <span class="vl" style="${over?'color:var(--danger)':''}">${v.total-used}/${v.total}</span>
      </div>`;
    }).join('');

    document.getElementById('lv-msg').textContent = '';
  }

  cal.addEventListener('click', e=>{
    const b = e.target.closest('[data-d]');
    if(!b) return;
    const d = +b.dataset.d;
    if(isWeekend(d)) return;
    selected.has(d) ? selected.delete(d) : selected.add(d);
    resetChain();
    render();
  });

  document.querySelectorAll('[data-lt]').forEach(b=>{
    b.addEventListener('click', ()=>{
      document.querySelectorAll('[data-lt]').forEach(x=>x.setAttribute('aria-pressed','false'));
      b.setAttribute('aria-pressed','true');
      type = b.dataset.lt;
      render();
    });
  });

  let chainTimers = [];
  function resetChain(){
    chainTimers.forEach(clearTimeout); chainTimers = [];
    ['ch-1','ch-2','ch-3'].forEach(id=>{
      const el = document.getElementById(id);
      if(el) el.classList.remove('done','active');
    });
  }
  function runChain(){
    resetChain();
    const steps = ['ch-1','ch-2','ch-3'];
    steps.forEach((id,i)=>{
      chainTimers.push(setTimeout(()=>{
        const el = document.getElementById(id); if(!el) return;
        el.classList.add('active');
        if(i>0){ const prev=document.getElementById(steps[i-1]); prev.classList.remove('active'); prev.classList.add('done'); }
      }, 500 + i*1100));
    });
    chainTimers.push(setTimeout(()=>{
      const el = document.getElementById('ch-3');
      if(el){ el.classList.remove('active'); el.classList.add('done'); }
    }, 500 + 3*1100));
  }

  document.getElementById('lv-reset').addEventListener('click', ()=>{ selected.clear(); resetChain(); render(); });
  document.getElementById('lv-submit').addEventListener('click', ()=>{
    const total = selected.size + sandwichDays().length;
    const msg = document.getElementById('lv-msg');
    if(!total){ msg.style.color='var(--fg-3)'; msg.textContent='Select at least one date.'; return; }
    msg.style.color='var(--ok)';
    msg.textContent = `Request for ${total} ${total===1?'day':'days'} routed for approval.`;
    runChain();
  });

  render();
}

/* ---------- Approval rule builder ---------- */
function initRuleBuilder(){
  const set = document.getElementById('rule-set');
  if(!set) return;

  const RULES = [
    {if:'Duration is <b>1–2 days</b>', dept:null, chain:['L1 — Reporting manager']},
    {if:'Duration is <b>3–5 days</b>', dept:null, chain:['L1 — Reporting manager','L2 — HR head']},
    {if:'Duration is <b>6–10 days</b>', dept:null, chain:['L1 — Reporting manager','L2 — HR head','L3 — Department head']},
    {if:'Duration is <b>over 10 days</b>', dept:null, chain:['L1 — Reporting manager','L2 — HR head','L3 — Department head','L4 — Director']},
    {if:'Requester is in <b>HR &amp; Admin</b>', dept:'hr', chain:['L1 — HR head','L2 — Director'], note:'Overrides duration rules'}
  ];
  const PEOPLE = {
    'L1 — Reporting manager':'Ravi S.',
    'L2 — HR head':'Priya M.',
    'L3 — Department head':'Kavya N.',
    'L4 — Director':'Anand R.',
    'L1 — HR head':'Priya M.',
    'L2 — Director':'Anand R.'
  };

  function matchIndex(days, dept){
    if(dept === 'hr') return 4;
    if(days <= 2) return 0;
    if(days <= 5) return 1;
    if(days <= 10) return 2;
    return 3;
  }

  function render(){
    const days = +document.getElementById('sim-days').value;
    const dept = document.getElementById('sim-dept').value;
    const hit = matchIndex(days, dept);

    set.innerHTML = RULES.map((r,i)=>`
      <div class="rulecard${i===hit?' hit':''}">
        <div class="rule-top">
          <span class="rule-n">R${i+1}</span>
          <span class="rule-if">${r.if}</span>
          ${i===hit?`<span class="rule-flag">Matched</span>`:''}
        </div>
        <div class="rule-then">${r.chain.map(c=>`<span class="rule-lvl">${c}</span>`).join('')}</div>
        ${r.note?`<p class="small" style="margin-top:7px;font-size:.7rem;color:var(--fg-4)">${r.note}</p>`:''}
      </div>`).join('');

    document.getElementById('sim-days-v').textContent = days + (days===1?' day':' days');

    const chain = RULES[hit].chain;
    document.getElementById('sim-chain').innerHTML =
      `<div class="chain-s done"><span class="chain-d"></span><b>Arjun R.</b><span>Requester — applied</span></div>` +
      chain.map((c,i)=>`
        <div class="chain-s${i===0?' active':''}">
          <span class="chain-d"></span>
          <b>${PEOPLE[c]||'—'}</b>
          <span>${c}</span>
        </div>`).join('');

    const deptName = {eng:'Engineering', sales:'Sales', hr:'HR & Admin'}[dept];
    document.getElementById('sim-why').innerHTML = dept === 'hr'
      ? `<strong>Rule 5 matched.</strong> Requests from HR &amp; Admin can't be approved by HR itself — the chain reroutes to the director regardless of duration. This exception was invisible in the written requirement and only surfaced during workflow shadowing.`
      : `<strong>Rule ${hit+1} matched.</strong> ${days} ${days===1?'day':'days'} in ${deptName} routes through ${chain.length} ${chain.length===1?'approver':'approvers'}. No one had to know that — the policy decided it.`;
  }

  document.getElementById('sim-days').addEventListener('input', render);
  document.getElementById('sim-dept').addEventListener('change', render);
  render();
}

/* ---------- AI candidate matching ---------- */
function initHiring(){
  const skillsEl = document.getElementById('skills');
  if(!skillsEl) return;

  const SKILLS = [
    {k:'Figma', req:true},
    {k:'UX research', req:true},
    {k:'Design systems', req:true},
    {k:'Prototyping', req:false},
    {k:'SaaS products', req:false},
    {k:'Front-end code', req:false}
  ];
  const CANDS = [
    {n:'Kavya S.', exp:'5 yrs', has:['Figma','UX research','Design systems','Prototyping','SaaS products'], low:null},
    {n:'Rohit A.', exp:'4 yrs', has:['Figma','UX research','Design systems','Front-end code'], low:'Design systems'},
    {n:'Meera T.', exp:'3 yrs', has:['Figma','Prototyping','SaaS products'], low:null},
    {n:'Imran K.', exp:'6 yrs', has:['Figma','UX research','SaaS products','Front-end code'], low:'UX research'}
  ];
  const active = new Set(SKILLS.map(s=>s.k));

  function score(c){
    let got=0, tot=0;
    SKILLS.forEach(s=>{
      if(!active.has(s.k)) return;
      const w = s.req ? 2 : 1;
      tot += w;
      if(c.has.includes(s.k)) got += w;
    });
    return tot ? Math.round((got/tot)*100) : 0;
  }

  function render(){
    skillsEl.innerHTML = SKILLS.map(s=>`
      <button class="skill" data-sk="${s.k}" aria-pressed="${active.has(s.k)}">
        ${s.k}<span class="w">${s.req?'×2':'×1'}</span>
      </button>`).join('');

    const ranked = CANDS.map(c=>({...c, pct:score(c)})).sort((a,b)=>b.pct-a.pct);
    document.getElementById('cand-count').textContent =
      `${active.size} ${active.size===1?'criterion':'criteria'} active`;

    document.getElementById('cands').innerHTML = ranked.map((c,i)=>{
      const col = c.pct>=80?'var(--ok)':c.pct>=55?'var(--warn)':'var(--fg-3)';
      return `<div class="cand${i===0&&c.pct>0?' top':''}">
        <div class="cand-h">
          <b>${c.n}<em>${c.exp}</em></b>
          <span class="cand-pct" style="color:${col}">${c.pct}%</span>
        </div>
        <span class="cand-bar"><i style="width:${c.pct}%;background:${col}"></i></span>
        <div class="cand-sk">
          ${SKILLS.filter(s=>active.has(s.k)).map(s=>
            c.has.includes(s.k)
              ? `<span class="has">${s.k}</span>`
              : `<span class="miss">${s.k}</span>`
          ).join('')}
        </div>
        ${c.low && active.has(c.low) ? `<p class="cand-note">${I.warn} Low-confidence extraction on "${c.low}" — verify before relying on this score</p>` : ''}
      </div>`;
    }).join('');
  }

  skillsEl.addEventListener('click', e=>{
    const b = e.target.closest('[data-sk]');
    if(!b) return;
    const k = b.dataset.sk;
    if(active.has(k)){ if(active.size===1) return; active.delete(k); }
    else active.add(k);
    render();
  });

  render();
}

/* ---------- HR chatbot ---------- */
function initBot(){
  const chat = document.getElementById('chat');
  if(!chat) return;

  const Q = [
    {q:'How many leaves do I have left?', a:'You have <strong>8 casual</strong> and <strong>12 earned</strong> leaves remaining for FY 2026. Want me to apply one for you?'},
    {q:'Send me my March payslip', a:'Sent to <strong>arjun.r@company.in</strong> just now. Net pay for March was <strong>₹63,000</strong>. It\'s also in Payroll → My payslips.'},
    {q:'What is the WFH policy?', a:'<strong>Work from home policy v2.0</strong> — up to 8 days a month with manager approval, requested at least a day ahead. You last acknowledged this version on 15 Dec 2025.'},
    {q:'Can I encash my unused leaves this year?', edge:true, handoff:{
      got:'Leave encashment enquiry',
      cant:'Encashment eligibility depends on your contract type and this financial year\'s policy exception, which I can\'t read',
      who:'Priya M. — HR Head',
      sla:'Usually replies within 4 working hours'
    }}
  ];
  let used = new Set();

  function scroll(){ chat.scrollTop = chat.scrollHeight; }
  function add(html, cls){
    const d = document.createElement('div');
    d.className = cls;
    d.innerHTML = html;
    chat.appendChild(d);
    scroll();
    return d;
  }
  function renderSug(){
    document.getElementById('chat-sug').innerHTML = Q.map((x,i)=>
      `<button class="sug${x.edge?' edge':''}" data-q="${i}" ${used.has(i)?'disabled':''}>${x.q}</button>`
    ).join('');
  }

  function ask(i){
    if(used.has(i)) return;
    used.add(i);
    renderSug();
    const item = Q[i];
    add(item.q, 'msg me');
    const t = add('<i></i><i></i><i></i>', 'msg bot typing');
    setTimeout(()=>{
      t.remove();
      if(item.handoff){
        const h = item.handoff;
        add(`
          <p class="hl-t">${I.warn} I can't answer this one — here's who can</p>
          <dl>
            <dt>Understood</dt><dd>${h.got}</dd>
            <dt>Blocked by</dt><dd>${h.cant}</dd>
            <dt>Owner</dt><dd>${h.who}</dd>
            <dt>Response</dt><dd>${h.sla}</dd>
          </dl>
          <div class="hb">
            <span class="btn btn-p" style="font-size:.78rem;padding:7px 14px">Send to Priya with this context</span>
            <span class="btn btn-s" style="font-size:.78rem;padding:7px 14px">Read the leave policy</span>
          </div>`, 'handoff');
      } else {
        add(item.a, 'msg bot');
      }
    }, 850);
  }

  document.getElementById('chat-sug').addEventListener('click', e=>{
    const b = e.target.closest('[data-q]');
    if(b && !b.disabled) ask(+b.dataset.q);
  });

  add('Hi Arjun — I can help with leave, payslips and policies. What do you need?', 'msg bot');
  renderSug();
}

/* ---------- Policy versioning ---------- */
function initPolicyVersion(){
  const btn = document.getElementById('pol-publish');
  if(!btn) return;
  let minor = 1;
  btn.addEventListener('click', ()=>{
    minor++;
    document.getElementById('pol-v').textContent = `v3.${minor}`;
    document.getElementById('ack-f').style.width = '0%';
    document.getElementById('ack-v').textContent = '0%';
    document.getElementById('pen-f').style.width = '100%';
    document.getElementById('pen-v').textContent = '100%';
    document.getElementById('pol-log').innerHTML =
      `<strong style="color:var(--warn)">v3.${minor} published.</strong> Acknowledgement state reset to zero — all 142 employees re-prompted. The v3.${minor-1} record is preserved and remains auditable.`;
    setTimeout(()=>{
      let p = 0;
      const t = setInterval(()=>{
        p += 7;
        if(p >= 61){ p = 61; clearInterval(t); }
        document.getElementById('ack-f').style.width = p+'%';
        document.getElementById('ack-v').textContent = p+'%';
        document.getElementById('pen-f').style.width = (100-p)+'%';
        document.getElementById('pen-v').textContent = (100-p)+'%';
      }, 90);
    }, 700);
  });
}

/* ---------- Cross-OS policy builder ---------- */
function initPolicyBuilder(){
  const tabsEl = document.getElementById('os-tabs');
  if(!tabsEl) return;

  const OS = [
    {k:'android', n:'Android', ic:'A'},
    {k:'windows', n:'Windows', ic:'W'},
    {k:'apple',   n:'Apple',   ic:'⌘'}
  ];
  const POLICIES = [
    {g:'Authentication & security', items:[
      {n:'Minimum password length', d:'8 characters, alphanumeric', os:['android','windows','apple'], on:true},
      {n:'Biometric authentication', d:'Allow fingerprint and face unlock', os:['android','windows','apple'], on:true},
      {n:'Screen lock timeout', d:'Auto-lock after 2 minutes idle', os:['android','windows','apple'], on:true},
      {n:'Factory reset protection', d:'Block device wipe without credentials', os:['android'], on:true},
      {n:'BitLocker disk encryption', d:'Enforce full-disk encryption', os:['windows'], on:true},
      {n:'FileVault encryption', d:'Enforce full-disk encryption', os:['apple'], on:false}
    ]},
    {g:'Network & VPN', items:[
      {n:'Always-on VPN', d:'Route all traffic through corporate VPN', os:['android'], on:true},
      {n:'Windows Firewall control', d:'Enforce firewall profile', os:['windows'], on:true},
      {n:'Block data roaming', d:'Prevent cellular data outside home network', os:['android'], on:false},
      {n:'Wi-Fi configuration', d:'Push corporate network profiles', os:['android','windows','apple'], on:true}
    ]},
    {g:'BYOD & data separation', items:[
      {n:'Copy & paste between profiles', d:'Block clipboard across work and personal', os:['android'], on:true},
      {n:'Block AirDrop', d:'Prevent local file sharing', os:['apple'], on:true},
      {n:'Cross-profile data sharing', d:'Restrict work data leaving the work profile', os:['android'], on:true},
      {n:'Lock screen message', d:'Display corporate contact details', os:['android','apple'], on:false}
    ]}
  ];

  let active = new Set(['android','windows','apple']);
  const state = {};
  POLICIES.forEach(g=>g.items.forEach(p=>{ state[p.n] = p.on; }));

  function counts(){
    let applicable = 0, enabled = 0;
    POLICIES.forEach(g=>g.items.forEach(p=>{
      const ok = p.os.some(o=>active.has(o));
      if(ok){ applicable++; if(state[p.n]) enabled++; }
    }));
    return {applicable, enabled};
  }

  function renderTabs(){
    tabsEl.innerHTML = OS.map(o=>{
      const c = POLICIES.reduce((s,g)=>s+g.items.filter(p=>p.os.includes(o.k)).length,0);
      return `<button class="os-tab" data-os="${o.k}" aria-pressed="${active.has(o.k)}">
        <span>${o.n}</span><span class="cnt">${c}</span>
      </button>`;
    }).join('');
  }

  function renderList(){
    document.getElementById('pol-list').innerHTML = POLICIES.map(g=>`
      <div class="pol-grp">${g.g}</div>
      ${g.items.map(p=>{
        const ok = p.os.some(o=>active.has(o));
        return `<div class="pol-r${ok?'':' na'}">
          <div class="pol-nm"><b>${p.n}</b><span>${p.d}</span></div>
          <div class="pol-os">${OS.map(o=>`<i class="${p.os.includes(o.k)&&active.has(o.k)?'on':''}" title="${o.n}">${o.ic}</i>`).join('')}</div>
          <button class="tgl" data-p="${p.n}" aria-pressed="${state[p.n]&&ok}" aria-label="${p.n}" ${ok?'':'disabled'}></button>
        </div>`;
      }).join('')}
    `).join('');

    const c = counts();
    document.getElementById('pb-applicable').textContent = c.applicable;
    document.getElementById('pb-enabled').textContent = c.enabled;
    document.getElementById('pb-os').textContent = active.size;
  }

  tabsEl.addEventListener('click', e=>{
    const b = e.target.closest('[data-os]');
    if(!b) return;
    const k = b.dataset.os;
    if(active.has(k)){ if(active.size === 1) return; active.delete(k); }
    else active.add(k);
    renderTabs(); renderList();
  });

  document.getElementById('pol-list').addEventListener('click', e=>{
    const b = e.target.closest('[data-p]');
    if(!b || b.disabled) return;
    state[b.dataset.p] = !state[b.dataset.p];
    renderList();
  });

  renderTabs(); renderList();
}

/* ---------- Destructive action safety ---------- */
function initWipe(){
  const actsEl = document.getElementById('acts');
  if(!actsEl) return;

  const ACTIONS = [
    {k:'lock',  n:'Lock device',     sev:'low',  rev:'Reversible — user can unlock with credentials'},
    {k:'pwd',   n:'Force password reset', sev:'med', rev:'Reversible — user sets a new password at next unlock'},
    {k:'retire',n:'Retire — remove work data', sev:'high', rev:'Work profile deleted. Personal data untouched'},
    {k:'wipe',  n:'Remote wipe',     sev:'critical', rev:'Irreversible — full factory reset, all data destroyed'}
  ];
  const TARGETS = {
    one:  {n:1,   label:'Dell XPS (Tom V.)', devices:[['Dell XPS 15','Tom V. · Finance']]},
    team: {n:12,  label:'Field Team', devices:[['iPad Pro','Meera K. · Field ops'],['Galaxy Tab S9','Raj P. · Field ops'],['Surface Go','Anita D. · Field ops']]},
    all:  {n:340, label:'All Windows devices', devices:[['Dell XPS 15','Tom V. · Finance'],['ThinkPad X1','Priya M. · HR'],['Surface Laptop 5','Anand R. · Director'],['Dell Latitude','Kavya N. · Engineering']]}
  };
  const SEV = {low:'var(--fg-3)', med:'var(--warn)', high:'var(--warn)', critical:'var(--danger)'};

  let action = 'lock';
  let undoTimer = null, undoInt = null;

  function clearTimers(){ clearTimeout(undoTimer); clearInterval(undoInt); undoTimer = undoInt = null; }

  function renderActs(){
    actsEl.innerHTML = ACTIONS.map(a=>`
      <button class="act" data-a="${a.k}" aria-pressed="${action===a.k}">
        <span class="act-dot" style="background:${SEV[a.sev]}"></span>
        <span class="act-n">${a.n}</span>
      </button>`).join('');
  }

  function render(){
    clearTimers();
    const a = ACTIONS.find(x=>x.k===action);
    const t = TARGETS[document.getElementById('wipe-target').value];
    const critical = a.sev==='critical' || (a.sev==='high' && t.n>10);
    const needsType = critical && t.n > 1;
    const phrase = t.n>100 ? `WIPE ${t.n}` : 'CONFIRM';

    document.getElementById('wipe-panel').innerHTML = `
      <p class="eyebrow" style="margin-bottom:14px">Blast radius</p>
      <div class="blast ${critical?'crit':''}">
        <div class="blast-n">
          <b style="color:${critical?'var(--danger)':SEV[a.sev]}">${t.n}</b>
          <span>${t.n===1?'device':'devices'} affected — ${t.label}</span>
        </div>
        <div class="blast-list">
          ${t.devices.map(([d,o])=>`<div class="blast-d"><b>${d}</b><span>${o}</span></div>`).join('')}
          ${t.n>t.devices.length?`<div class="blast-d more">+ ${t.n - t.devices.length} more devices and owners</div>`:''}
        </div>
        <p class="blast-rev">${a.rev}</p>
      </div>
      ${needsType ? `
        <div class="typebox">
          <label for="wipe-type">Type <b>${phrase}</b> to enable this action</label>
          <input id="wipe-type" class="typein" placeholder="${phrase}" autocomplete="off" aria-label="Confirmation phrase">
        </div>` : ''}
      <button class="btn ${critical?'btn-danger':'btn-s'}" id="wipe-go" style="margin-top:18px;font-size:.85rem;padding:10px 18px" ${needsType?'disabled':''}>
        ${a.n}${t.n>1?` — ${t.n} devices`:''}
      </button>
      <div id="wipe-result" style="margin-top:16px"></div>`;

    if(needsType){
      const inp = document.getElementById('wipe-type');
      inp.addEventListener('input', ()=>{
        document.getElementById('wipe-go').disabled = inp.value.trim().toUpperCase() !== phrase;
      });
    }
    document.getElementById('wipe-go').addEventListener('click', ()=>dispatch(a,t));
  }

  function dispatch(a,t){
    clearTimers();
    const res = document.getElementById('wipe-result');
    document.getElementById('wipe-go').disabled = true;
    let left = 10;
    res.innerHTML = `
      <div class="undo">
        <div class="undo-top">
          <span class="undo-ring"><svg width="30" height="30" viewBox="0 0 30 30"><circle cx="15" cy="15" r="12" fill="none" stroke="var(--t5)" stroke-width="2.5"/><circle id="undo-arc" cx="15" cy="15" r="12" fill="none" stroke="var(--ac)" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="75.4" stroke-dashoffset="0" transform="rotate(-90 15 15)"/></svg><b id="undo-n">${left}</b></span>
          <div>
            <b>${a.n} queued</b>
            <span>Dispatching to ${t.n} ${t.n===1?'device':'devices'} in <span id="undo-s">${left}</span>s</span>
          </div>
        </div>
        <button class="btn btn-s" id="undo-btn" style="font-size:.8rem;padding:8px 16px">Cancel</button>
      </div>`;

    undoInt = setInterval(()=>{
      left--;
      const n = document.getElementById('undo-n'), s = document.getElementById('undo-s'), arc = document.getElementById('undo-arc');
      if(!n){ clearTimers(); return; }
      n.textContent = left; s.textContent = left;
      arc.setAttribute('stroke-dashoffset', String(75.4 * (1 - left/10)));
      if(left<=0) clearInterval(undoInt);
    }, 1000);

    undoTimer = setTimeout(()=>{
      clearTimers();
      res.innerHTML = `<div class="dispatched"><b>Dispatched.</b> Logged to the audit trail — attributed to your account, timestamped, and reconstructable during a security audit.</div>`;
      setTimeout(render, 2600);
    }, 10000);

    document.getElementById('undo-btn').addEventListener('click', ()=>{
      clearTimers();
      res.innerHTML = `<div class="cancelled"><b>Cancelled.</b> Nothing was sent. This is the layer that prevents the Monday-morning incident — prevention alone isn't enough, you need recovery.</div>`;
      setTimeout(render, 2600);
    });
  }

  actsEl.addEventListener('click', e=>{
    const b = e.target.closest('[data-a]');
    if(!b) return;
    action = b.dataset.a;
    renderActs(); render();
  });
  document.getElementById('wipe-target').addEventListener('change', render);

  renderActs(); render();
}

/* ---------- Compliance triage ---------- */
function initCompliance(){
  const alertsEl = document.getElementById('alerts');
  if(!alertsEl) return;

  const ALERTS = [
    {sev:'critical', t:'BitLocker not enforced on 38 Windows devices', d:'Disk encryption policy failed to apply after the 14.3 update. These devices hold customer data.', fix:'Re-push encryption policy', when:'2h ago', n:38},
    {sev:'critical', t:'Factory reset attempted — blocked by policy', d:'iPad Pro (Field Team). Reset protection held. Device flagged for physical verification.', fix:'Verify device custody', when:'3h ago', n:1},
    {sev:'warning', t:'Compliance drift on 6 devices', d:'Local admin re-enabled after policy application. Common after major OS updates.', fix:'Reapply Corp-Strict profile', when:'5h ago', n:6},
    {sev:'warning', t:'14 devices offline beyond 7 days', d:'No check-in. Policy state cannot be confirmed and may have drifted.', fix:'Flag for IT follow-up', when:'1d ago', n:14},
    {sev:'info', t:'23 devices pending OS update', d:'Security patch available, not yet installed. Within the 14-day grace window.', fix:'Schedule update wave', when:'1d ago', n:23},
    {sev:'info', t:'Policy applied — Corp-Strict', d:'Samsung S24 (Priya M.) enrolled and fully configured.', fix:'No action needed', when:'2d ago', n:1}
  ];
  const META = {
    critical:{c:'var(--danger)', bg:'var(--danger-bg)', l:'Critical'},
    warning: {c:'var(--warn)',   bg:'var(--warn-bg)',   l:'Warning'},
    info:    {c:'var(--fg-3)',   bg:'var(--t2)', l:'Info'}
  };
  let filter = 'all';

  function render(){
    const list = ALERTS.filter(a=>filter==='all'||a.sev===filter);
    const devices = list.reduce((s,a)=>s+a.n,0);
    alertsEl.innerHTML = `
      <p class="small" style="margin-bottom:14px;color:var(--fg-3);font-size:.79rem">
        <strong>${list.length}</strong> ${list.length===1?'item':'items'} · <strong>${devices}</strong> ${devices===1?'device':'devices'} affected · ranked by severity, not recency
      </p>
      ${list.map(a=>{
        const m = META[a.sev];
        return `<div class="alert-r" style="border-left-color:${m.c}">
          <div class="alert-hd">
            <span class="alert-sev" style="color:${m.c};background:${m.bg};border-color:${m.c}">${m.l}</span>
            <b>${a.t}</b>
            <span class="alert-when">${a.when}</span>
          </div>
          <p>${a.d}</p>
          <div class="alert-ft">
            <span class="alert-fix">Remediation: <b>${a.fix}</b></span>
            <span class="alert-n">${a.n} ${a.n===1?'device':'devices'}</span>
          </div>
        </div>`;
      }).join('') || `<div class="callout">Nothing at this severity. That's the point — an empty queue is a valid and desirable state.</div>`}`;
  }

  document.getElementById('sev-seg').addEventListener('click', e=>{
    const b = e.target.closest('[data-sev]');
    if(!b) return;
    document.querySelectorAll('#sev-seg [data-sev]').forEach(x=>x.setAttribute('aria-pressed','false'));
    b.setAttribute('aria-pressed','true');
    filter = b.dataset.sev;
    render();
  });

  render();
}

const REDUCED = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const TIMERS = [];
function later(fn, ms){ const t = setTimeout(fn, ms); TIMERS.push(t); return t; }
function clearTimers(){ while(TIMERS.length){ const t=TIMERS.pop(); clearTimeout(t); clearInterval(t); } }

/* ---------- Service request routing ---------- */
function initAssign(){
  const tabs = document.getElementById('sr-tabs');
  if(!tabs) return;

  const ENG = [
    {n:'Kavya N.', skills:['hardware','asset store','endpoint'], shift:true,  load:3, w:4, mix:'3 open · all routine'},
    {n:'Ravi S.',  skills:['identity','licensing','endpoint'],   shift:true,  load:2, w:9, mix:'2 open · both P1'},
    {n:'Tom V.',   skills:['hardware','network'],                shift:false, load:1, w:2, mix:'1 open · routine'},
    {n:'Meera K.', skills:['identity','licensing'],              shift:true,  load:4, w:5, mix:'4 open · one P2'}
  ];
  const REQ = [
    {label:'New laptop — Finance', need:'hardware', item:'Hardware · Laptop (standard build)',
     note:'Two engineers hold the hardware certification. One is off shift, so the choice is made on weighted load.'},
    {label:'Figma licence', need:'licensing', item:'Software · Design tooling licence',
     note:'This is the case that killed round robin. Ravi holds <strong>fewer</strong> tickets than Meera — two against four — so a count-based rule hands it to him. But both of his are P1. Weighted load sends it to Meera instead.'},
    {label:'VPN access — contractor', need:'identity', item:'Access · Remote network profile',
     note:'Identity-certified only, so the same two engineers qualify and the same weighting applies. The reasoning is identical every time, which is exactly what makes an automated assignment arguable rather than arbitrary.'}
  ];
  let active = 0, step = -1, timers = [];

  const clear = () => { timers.forEach(clearTimeout); timers = []; };

  function eligible(){
    const need = REQ[active].need;
    return ENG.map(e=>({...e,
      skillOk: e.skills.includes(need),
      ok: e.skills.includes(need) && e.shift
    }));
  }
  function winner(){
    const el = eligible().filter(e=>e.ok);
    return el.sort((a,b)=>a.w-b.w)[0];
  }

  function render(){
    tabs.innerHTML = REQ.map((r,i)=>
      `<button class="tk-tab" data-sr="${i}" aria-pressed="${i===active}">${r.label}</button>`).join('');

    const STEPS = [
      {t:'Catalogue item matched', d:REQ[active].item},
      {t:'Filter by certification', d:`Engineers certified for "${REQ[active].need}"`},
      {t:'Filter by shift', d:'On-shift only — off-shift engineers are excluded, not queued'},
      {t:'Lowest weighted load', d:'A P1 counts heavier than a routine request'},
      {t:'Assigned', d: step>=4 ? `Routed to ${winner().n} — reasoning attached to the ticket` : 'Awaiting evaluation'}
    ];
    document.getElementById('sr-steps').innerHTML = STEPS.map((s,i)=>`
      <div class="sr-s ${i<step?'on':i===step?'run':''}">
        <span class="sr-n">${i<step?'✓':i+1}</span>
        <div><b>${s.t}</b><span>${s.d}</span></div>
      </div>`).join('');

    const w = winner();
    document.getElementById('sr-eng').innerHTML = eligible().map(e=>{
      let cls = '';
      if(step >= 4 && e.n === w.n) cls = 'pick';
      else if(step >= 2 && !e.ok) cls = 'out';
      else if(step >= 1 && !e.skillOk) cls = 'out';
      else if(step >= 1) cls = 'elig';
      const lp = Math.min(100, (e.w/10)*100);
      const col = e.w>=8?'var(--danger)':e.w>=4?'var(--warn)':'var(--ok)';
      return `<div class="eng-c ${cls}">
        <div class="eng-h">
          <b>${e.n}</b>
          ${step>=4 && e.n===w.n ? `<span class="eng-tag" style="color:var(--ac);border-color:var(--ac)">Assigned</span>`
            : !e.shift ? `<span class="eng-tag" style="color:var(--fg-4);border-color:var(--line-2)">Off shift</span>`
            : !e.skillOk && step>=1 ? `<span class="eng-tag" style="color:var(--fg-4);border-color:var(--line-2)">Not certified</span>` : ''}
        </div>
        <div class="eng-l">
          <span>Weighted</span>
          <span class="eng-tr"><span class="eng-f" style="width:${lp}%;background:${col}"></span></span>
          <span class="eng-v">${e.w} pts</span>
        </div>
        <span class="eng-sk">${e.mix} &nbsp;·&nbsp; ${e.skills.join(' · ')}</span>
      </div>`;
    }).join('');

    document.getElementById('sr-note').innerHTML = step>=4
      ? `<strong style="color:var(--ac)">${winner().n} takes it.</strong> ${REQ[active].note}`
      : `Routing…`;
  }

  function run(){
    clear(); step = 0; render();
    for(let i=1;i<=4;i++){
      timers.push(setTimeout(()=>{ step = i; render(); }, i*(REDUCED()?1:620)));
      TIMERS.push(timers[timers.length-1]);
    }
  }

  tabs.addEventListener('click', e=>{
    const b = e.target.closest('[data-sr]');
    if(!b) return;
    active = +b.dataset.sr; run();
  });
  run();
}

/* ---------- Workflow automation ---------- */
function initAuto(){
  const list = document.getElementById('auto-list');
  if(!list) return;

  const RULES = [
    {
      when:'a P1 incident goes unassigned for 15 minutes',
      iff:'it is outside business hours',
      then:'page the on-call engineer and notify the service desk manager',
      last:'Fired 3× this week · last 02:14 on INC-4712',
      steps:[
        ['Trigger matched','INC-4821 · P1 · unassigned 15m 02s','var(--ac)'],
        ['Condition','Outside business hours — 21:47 IST · true','var(--fg-3)'],
        ['Action','Paged Kavya N. (on-call rota)','var(--ok)'],
        ['Action','Notified Priya M. — service desk manager','var(--ok)'],
        ['Logged','Rule execution attached to INC-4821 history','var(--ok)']
      ]
    },
    {
      when:'a ticket reaches 80% of its SLA window',
      iff:'it has had no agent response',
      then:'escalate to the team lead and flag it in the queue',
      last:'Fired 14× this week · last 09:42 on INC-4788',
      steps:[
        ['Trigger matched','INC-4779 · 80% of SLA consumed','var(--ac)'],
        ['Condition','First response recorded — false','var(--fg-3)'],
        ['Action','Escalated to Ravi S. — team lead','var(--ok)'],
        ['Action','Queue flag raised — ticket now sorts to the top','var(--ok)'],
        ['Logged','Escalation reason recorded for the SLA report','var(--ok)']
      ]
    },
    {
      when:'a service request is approved',
      iff:'the catalogue item has a fulfilment team',
      then:'auto-assign by weighted load and notify the requester',
      last:'Fired 61× this week · last 11:08 on REQ-2204',
      steps:[
        ['Trigger matched','REQ-2210 · Laptop (standard build) · approved','var(--ac)'],
        ['Condition','Fulfilment team present — Endpoint Services · true','var(--fg-3)'],
        ['Action','Assigned to Kavya N. — lowest weighted load','var(--ok)'],
        ['Action','Requester notified with expected fulfilment date','var(--ok)'],
        ['Logged','Assignment reasoning attached to REQ-2210','var(--ok)']
      ]
    },
    {
      when:'the same incident is reported 3+ times in 24 hours',
      iff:'no problem record exists',
      then:'create a problem record and link every related incident',
      last:'Fired 2× this week · last 16:30 on PRB-118',
      steps:[
        ['Trigger matched','4 incidents matching "VPN drops" in 24h','var(--ac)'],
        ['Condition','Existing problem record — none found','var(--fg-3)'],
        ['Action','Created PRB-121 — VPN session instability','var(--ok)'],
        ['Action','Linked INC-4821, 4823, 4830, 4841','var(--ok)'],
        ['Logged','Problem owner assigned to Network Services','var(--ok)']
      ]
    }
  ];
  let running = -1;

  function render(){
    list.innerHTML = RULES.map((r,i)=>`
      <div class="auto-r ${running===i?'running':''}">
        <div class="auto-h">
          <span class="auto-sent">
            <em>When</em>${r.when}, <em>if</em>${r.iff}, <em>then</em><b>${r.then}</b>.
          </span>
          <span class="auto-meta">
            <span class="auto-last">${r.last}</span>
            <button class="auto-btn" data-run="${i}" ${running>-1?'disabled':''}>${running===i?'Running…':'Run'}</button>
          </span>
        </div>
        <div class="auto-log" id="alog-${i}"></div>
      </div>`).join('');
  }

  function run(i){
    if(running > -1) return;
    running = i; render();
    clearTimers();
    const log = document.getElementById('alog-'+i);
    log.classList.add('open');
    const r = RULES[i];
    const D = REDUCED() ? 1 : 620;
    r.steps.forEach((s,k)=>{
      later(()=>{
        const d = document.createElement('div');
        d.className='auto-step';
        d.innerHTML = `<i style="background:${s[2]}"></i><b>${s[0]}</b><span>${s[1]}</span>`;
        log.appendChild(d);
      }, k*D);
    });
    later(()=>{
      running = -1;
      const html = log.innerHTML;
      render();
      const l2 = document.getElementById('alog-'+i);
      l2.innerHTML = html; l2.classList.add('open');
      document.getElementById('auto-note').innerHTML =
        `<strong style="color:var(--ok)">Rule completed.</strong> Every step is written to the ticket's history — so six months later, "why did this escalate?" is answerable from the record instead of from memory.`;
    }, r.steps.length*D + 380);
  }

  list.addEventListener('click', e=>{
    const b = e.target.closest('[data-run]');
    if(b && !b.disabled) run(+b.dataset.run);
  });
  render();
}

/* ---------- AI recruitment pipeline ---------- */
function initRecruit(){
  const nav = document.getElementById('rec-nav');
  if(!nav) return;

  const STAGES = [
    {k:'Generate', n:'Job description'},
    {k:'Parse',    n:'Resume extraction'},
    {k:'Match',    n:'Skill ranking'},
    {k:'Schedule', n:'Interview booking'}
  ];
  const JD = `Senior Product Designer · Engineering · Bengaluru

We're looking for a designer who owns the experience end to end — from research through to delivered interface. You'll shape our design system, define interaction patterns, and work closely with product and engineering.

Required: Figma, UX research, design systems, 5+ years shipping SaaS products.`;

  const FIELDS = [
    ['Name','Kavya S.'],
    ['Experience','5 years — 3 in enterprise SaaS'],
    ['Skills','Figma · UX research · Design systems · Prototyping'],
    ['Education','B.Des, Communication Design', 'Low confidence'],
    ['Portfolio','kavyas.design — 4 case studies']
  ];

  let stage = -1, done = -1;

  function tabs(){
    nav.innerHTML = STAGES.map((s,i)=>`
      <div class="rec-t ${i===stage?'active':i<=done?'done':''}">
        <span class="st">Stage ${i+1}</span><b>${s.n}</b>
      </div>`).join('');
  }

  function setNote(html){ document.getElementById('rec-note').innerHTML = html; }
  function setStatus(t){ document.getElementById('rec-status').textContent = t; }

  function stageIdle(){
    document.getElementById('rec-stage').innerHTML =
      `<p class="small" style="color:var(--fg-4)">Press run to generate a job description, parse a resume against it, rank the candidate and book the interview.</p>`;
  }

  function typeJD(cb){
    const el = document.getElementById('rec-stage');
    el.innerHTML = `<p class="eyebrow" style="margin-bottom:12px">AI-generated · editable per section</p><div class="rec-jd" id="jd"></div>`;
    const jd = document.getElementById('jd');
    if(REDUCED()){ jd.textContent = JD; cb(); return; }
    let i = 0;
    const t = setInterval(()=>{
      i += 4;
      jd.innerHTML = JD.slice(0,i).replace(/</g,'&lt;') + '<span class="rec-cursor"></span>';
      if(i >= JD.length){ clearInterval(t); jd.textContent = JD; cb(); }
    }, 16);
    TIMERS.push(t);
  }

  function parse(cb){
    const el = document.getElementById('rec-stage');
    el.innerHTML = `<p class="eyebrow" style="margin-bottom:12px">Extracted from Kavya_S_Resume.pdf</p>
      <dl class="rec-fields">${FIELDS.map((f,i)=>`
        <div class="rec-f" id="rf-${i}">
          <dt>${f[0]}</dt><dd>${f[1]}</dd>
          ${f[2]?`<span class="warnflag">${f[2]}</span>`:'<span></span>'}
        </div>`).join('')}</dl>`;
    FIELDS.forEach((f,i)=>{
      later(()=>{ const r=document.getElementById('rf-'+i); if(r) r.classList.add('in'); }, REDUCED()?1:i*260);
    });
    later(cb, REDUCED()?10:FIELDS.length*260 + 400);
  }

  function match(cb){
    const el = document.getElementById('rec-stage');
    el.innerHTML = `<p class="eyebrow" style="margin-bottom:14px">Scored against the generated requirements</p>
      <div class="cands">
        <div class="cand top">
          <div class="cand-h"><b>Kavya S.<em>5 yrs</em></b><span class="cand-pct" id="mpct" style="color:var(--ok)">0%</span></div>
          <span class="cand-bar"><i id="mbar" style="width:0%;background:var(--ok)"></i></span>
          <div class="cand-sk">
            <span class="has">Figma</span><span class="has">UX research</span>
            <span class="has">Design systems</span><span class="has">Prototyping</span>
            <span class="miss">5+ yrs SaaS</span>
          </div>
          <p class="cand-note">${I.warn} Education field was low-confidence at parse — it does not contribute to this score</p>
        </div>
      </div>`;
    if(REDUCED()){ document.getElementById('mpct').textContent='89%'; document.getElementById('mbar').style.width='89%'; cb(); return; }
    let v=0;
    const t=setInterval(()=>{
      v+=3; if(v>=89){v=89;clearInterval(t);cb();}
      document.getElementById('mpct').textContent=v+'%';
      document.getElementById('mbar').style.width=v+'%';
    },26);
    TIMERS.push(t);
  }

  function schedule(cb){
    const el = document.getElementById('rec-stage');
    el.innerHTML = `<p class="eyebrow" style="margin-bottom:12px">Google Calendar — booked on confirmation</p><div class="rec-cal" id="cal2"></div>`;
    const evs = [
      ['Design round — Kavya S.','Wed 9 Apr · 11:00'],
      ['Panel: Ravi S. + Priya M.','60 min · Meet link sent'],
      ['Feedback form scheduled','Due 2h after the session']
    ];
    evs.forEach((e,i)=>{
      later(()=>{
        const d=document.createElement('div');
        d.className='rec-ev';
        d.innerHTML=`<span class="dot"></span><b>${e[0]}</b><span>${e[1]}</span>`;
        document.getElementById('cal2').appendChild(d);
      }, REDUCED()?1:i*380);
    });
    later(cb, REDUCED()?10:evs.length*380+300);
  }

  const NOTES = [
    `<strong>Stage 1.</strong> The model drafts from a title and department. Every section is editable and regenerable — HR owns the final wording, because a JD is a legal and brand artifact, not just a prompt output.`,
    `<strong style="color:var(--warn)">Stage 2 — the interesting one.</strong> Education parsed at low confidence and is flagged rather than silently accepted. <span class="hl">This is the failure that would otherwise be invisible three steps later,</span> when a ranking quietly includes a field the model guessed.`,
    `<strong>Stage 3.</strong> The score decomposes into matched and missing skills, and explicitly excludes the low-confidence field. A reviewer can see what the number is made of.`,
    `<strong style="color:var(--ok)">Stage 4.</strong> On confirmation, interviews book themselves with the panel and a feedback deadline. The pipeline is finished — but note that a human decided at every stage that mattered.`
  ];

  function run(){
    clearTimers();
    stage = 0; done = -1; tabs(); setStatus('Running…');
    document.getElementById('rec-run').disabled = true;
    const seq = [typeJD, parse, match, schedule];
    const step = i => {
      if(i >= seq.length){
        done = 3; stage = -1; tabs();
        setStatus('Complete'); document.getElementById('rec-run').disabled = false;
        return;
      }
      stage = i; done = i-1; tabs(); setNote(NOTES[i]);
      seq[i](()=> later(()=>step(i+1), 520));
    };
    step(0);
  }

  document.getElementById('rec-run').addEventListener('click', run);
  document.getElementById('rec-reset').addEventListener('click', ()=>{
    clearTimers(); stage=-1; done=-1; tabs(); stageIdle();
    setStatus(''); document.getElementById('rec-run').disabled=false;
    setNote('Four stages, each feeding the next. Press run — the interesting moment is stage two.');
  });

  tabs(); stageIdle();
}

/* ---------- QA bulk review ---------- */
function initReview(){
  const el = document.getElementById('rvw');
  if(!el) return;

  const GROUPS = [
    {g:'Functional', cases:[
      {t:'Sign in with valid credentials redirects to dashboard'},
      {t:'Session persists across a page refresh'},
      {t:'Sign out clears the session cookie'},
      {t:'Password reset email is dispatched on request'}
    ]},
    {g:'Negative', cases:[
      {t:'Sign in with an incorrect password shows a generic error', flag:'Domain judgement', why:'Generic vs specific error messaging is a security policy call the model cannot make.'},
      {t:'Expired reset token is rejected'},
      {t:'SQL injection in the email field is sanitised'}
    ]},
    {g:'Boundary', cases:[
      {t:'Password at minimum length (8) is accepted'},
      {t:'Password at maximum length (128) is accepted'},
      {t:'Email at 254 characters is accepted', flag:'Near-duplicate', why:'Overlaps TC-118 in the existing suite — approving both leaves you maintaining two tests for one behaviour.'}
    ]},
    {g:'Validation', cases:[
      {t:'Malformed email format is rejected before submit'},
      {t:'Required field messaging appears on empty submit', flag:'Low confidence', why:'The model inferred this from markup it could not fully parse. Worth a human read before it enters the suite.'}
    ]}
  ];

  let state = {}, clicks = 0;
  const key = (gi,ci) => gi+'-'+ci;
  function reset(){
    state = {}; clicks = 0;
    GROUPS.forEach((g,gi)=>g.cases.forEach((c,ci)=>{ state[key(gi,ci)] = 'pending'; }));
    render();
  }

  function counts(){
    let a=0,r=0,p=0,flagPending=0;
    GROUPS.forEach((g,gi)=>g.cases.forEach((c,ci)=>{
      const s = state[key(gi,ci)];
      if(s==='approved') a++; else if(s==='rejected') r++; else { p++; if(c.flag) flagPending++; }
    }));
    return {a,r,p,flagPending,total:a+r+p};
  }

  function render(){
    el.innerHTML = GROUPS.map((g,gi)=>{
      const plain = g.cases.filter(c=>!c.flag).length;
      const pendingPlain = g.cases.filter((c,ci)=>!c.flag && state[key(gi,ci)]==='pending').length;
      return `<div class="rvg">
        <div class="rvg-h">
          <b>${g.g}</b>
          <span class="n">${g.cases.length} generated${g.cases.length-plain ? ` · ${g.cases.length-plain} flagged` : ''}</span>
          <button class="rvg-btn" data-g="${gi}" ${pendingPlain?'':'disabled'}>
            ${pendingPlain ? `Approve ${pendingPlain} unflagged` : 'Nothing to batch'}
          </button>
        </div>
        ${g.cases.map((c,ci)=>{
          const s = state[key(gi,ci)];
          return `<div class="rvc ${s==='approved'?'approved':s==='rejected'?'rejected':''}">
            <span class="rvc-s">${s==='approved'?'✓':s==='rejected'?'✕':''}</span>
            <span class="rvc-t">${c.t}</span>
            ${c.flag?`<span class="rvc-flag" title="${c.why}">${c.flag}</span>`:''}
            <span class="rvc-acts">
              <button class="rvc-b ok" data-a="approve" data-k="${key(gi,ci)}" aria-label="Approve">✓</button>
              <button class="rvc-b no" data-a="reject"  data-k="${key(gi,ci)}" aria-label="Reject">✕</button>
            </span>
          </div>`;
        }).join('')}
      </div>`;
    }).join('');

    const c = counts();
    document.getElementById('rvw-counts').innerHTML = `
      <div><b style="color:var(--ok)">${c.a}</b><span>approved</span></div>
      <div><b style="color:var(--danger)">${c.r}</b><span>rejected</span></div>
      <div><b>${c.p}</b><span>still to review</span></div>
      <div><b style="color:var(--ac)">${clicks}</b><span>${clicks===1?'click':'clicks'} used</span></div>`;

    const v = document.getElementById('rvw-verdict');
    if(c.p === 0){
      v.innerHTML = `<strong style="color:var(--ok)">All 12 resolved in ${clicks} ${clicks===1?'click':'clicks'}.</strong> A flat list would have cost 12 separate decisions. The three flagged cases still needed a person — which is the point, not a shortcoming.`;
    } else if(c.flagPending && c.p === c.flagPending){
      v.innerHTML = `<strong style="color:var(--warn)">Only the flagged cases are left.</strong> Batch approval deliberately can't touch these: a near-duplicate, a security-policy judgement, and a low-confidence parse. <span class="hl">Your attention is now entirely on the ${c.flagPending} that need it.</span>`;
    } else {
      v.innerHTML = `Approve a whole group in one click. Flagged cases are excluded from batch actions by design — hover a flag to see why that one was held back.`;
    }
  }

  el.addEventListener('click', e=>{
    const g = e.target.closest('[data-g]');
    if(g && !g.disabled){
      const gi = +g.dataset.g;
      GROUPS[gi].cases.forEach((c,ci)=>{ if(!c.flag && state[key(gi,ci)]==='pending') state[key(gi,ci)]='approved'; });
      clicks++; render(); return;
    }
    const b = e.target.closest('[data-a]');
    if(b){
      state[b.dataset.k] = b.dataset.a === 'approve' ? 'approved' : 'rejected';
      clicks++; render();
    }
  });
  document.getElementById('rv-reset').addEventListener('click', reset);
  reset();
}

/* ---------- QA lifecycle pipeline ---------- */
function initPipe(){
  const el = document.getElementById('pipe');
  if(!el) return;

  const STAGES = [
    {n:'Generated',   own:'qa',  o:'QA',  d:'AI draft'},
    {n:'In review',   own:'qa',  o:'QA',  d:'Awaiting sign-off'},
    {n:'Approved',    own:'qa',  o:'QA',  d:'Ready for automation'},
    {n:'Script in dev',own:'dev', o:'Dev', d:'Playwright · Python'},
    {n:'Unit tested', own:'dev', o:'Dev', d:'Passing locally'},
    {n:'Submitted',   own:'dev', o:'Dev', d:'Back to QA'},
    {n:'Executed',    own:'qa',  o:'QA',  d:'Evidence captured'}
  ];
  const NOTES = [
    'Generated from URL discovery and waiting in the review workspace. Nobody owns it yet beyond QA.',
    'A QA engineer is accountable from here. The case cannot move without an explicit decision.',
    '<strong>Ownership transfers.</strong> The case leaves QA and becomes a work item for automation — same record, different face.',
    'The developer works against the approved case text. If the case is ambiguous, that surfaces now rather than after the script ships.',
    'Script passes locally. Still owned by the developer — "it works on my machine" is not a state QA can act on.',
    '<strong>Ownership transfers back.</strong> QA sees the script attached to the case they approved, with its unit test result.',
    '<strong>Complete.</strong> Screenshots and logs attach to the record. The full chain — origin, approval, script, run, evidence — is reconstructable from one place.'
  ];
  let i = 0, failed = false;

  function render(){
    el.innerHTML = STAGES.map((s,idx)=>{
      let cls = '';
      if(failed && idx===1) cls='failed';
      else if(idx < i) cls='done';
      else if(idx === i && !failed) cls='active';
      return `<div class="pst ${cls}">
        <span class="pst-own ${s.own}">${s.o}</span>
        <b>${s.n}</b><i>${s.d}</i>
      </div>`;
    }).join('');

    const note = document.getElementById('pipe-note');
    if(failed){
      note.innerHTML = `<strong style="color:var(--danger)">Rejected at review.</strong> The case returns to Generated with the QA engineer's reason attached to the record — not sent as a chat message that scrolls away. The next person to open it sees why it came back.`;
    } else {
      note.innerHTML = NOTES[Math.min(i, NOTES.length-1)];
    }
    document.getElementById('pipe-next').disabled = !failed && i >= STAGES.length-1;
  }

  document.getElementById('pipe-next').addEventListener('click', ()=>{
    if(failed){ failed=false; render(); return; }
    if(i < STAGES.length-1){ i++; render(); }
  });
  document.getElementById('pipe-fail').addEventListener('click', ()=>{ failed = true; i = 1; render(); });
  document.getElementById('pipe-reset').addEventListener('click', ()=>{ i=0; failed=false; render(); });
  render();
}

/* ---------- SLA triage queue ---------- */
function initQueue(){
  const el = document.getElementById('queue');
  if(!el) return;

  const TICKETS = [
    {id:'INC-4779', t:'New joiner account provisioning — starts Monday', who:'HR · onboarding',        pri:'P2', age:600, sla:35},
    {id:'INC-4788', t:'Outlook calendar not syncing across devices',     who:'Tom V. · Finance',       pri:'P3', age:520, sla:118},
    {id:'INC-4795', t:'Laptop replacement request',                      who:'Meera K. · Sales',       pri:'P4', age:420, sla:2200},
    {id:'INC-4802', t:'Cannot access the shared drive',                  who:'Ravi S. · Engineering',  pri:'P3', age:310, sla:890},
    {id:'INC-4821', t:'VPN dropping every 10 minutes — whole floor',     who:'Finance · 14 users',     pri:'P1', age:42,  sla:9},
    {id:'INC-4830', t:'Payroll portal returns 500 on timesheet submit',  who:'Priya M. · HR',          pri:'P1', age:12,  sla:47}
  ];
  const PRI = {P1:'var(--danger)', P2:'var(--warn)', P3:'var(--fg-3)', P4:'var(--fg-4)'};
  const CAP = 240; // ring scale in minutes
  let mode = 'sla', timer = null;

  const fmt = m => m <= 0 ? 'BREACH' : m >= 60 ? `${Math.floor(m/60)}h ${m%60}m` : `${m}m`;
  const ageFmt = m => m >= 60 ? `${Math.floor(m/60)}h open` : `${m}m open`;

  const C = 2 * Math.PI * 15;
  const state = t => {
    const breached = t.sla <= 0;
    return {
      breached,
      cls: breached ? 'breached' : t.sla < 15 ? 'crit' : t.sla < 60 ? 'warn' : '',
      col: breached || t.sla < 15 ? 'var(--danger)' : t.sla < 60 ? 'var(--warn)' : 'var(--ok)',
      dash: (C * (1 - Math.max(0, Math.min(1, t.sla / CAP)))).toFixed(1),
      label: breached ? '!' : (t.sla >= 60 ? Math.floor(t.sla/60)+'h' : t.sla+'m')
    };
  };
  let lastOrder = '';

  function render(){
    const rows = [...TICKETS].sort((a,b)=> mode==='age' ? b.age - a.age : a.sla - b.sla);
    const order = rows.map(t=>t.id).join();

    if(order !== lastOrder){
      // order actually changed — rebuild and let rows animate in
      lastOrder = order;
      el.innerHTML = rows.map(t=>{
        const s = state(t);
        return `<div class="qrow ${s.cls}" data-id="${t.id}">
          <span class="qring">
            <svg width="36" height="36" viewBox="0 0 36 36" aria-hidden="true">
              <circle cx="18" cy="18" r="15" fill="none" stroke="var(--t4)" stroke-width="2.5"/>
              <circle class="qarc" cx="18" cy="18" r="15" fill="none" stroke="${s.col}" stroke-width="2.5" stroke-linecap="round"
                stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${s.dash}" transform="rotate(-90 18 18)"/>
            </svg>
            <b style="color:${s.col}">${s.label}</b>
          </span>
          <span class="qmain"><b>${t.t}</b><span>${t.id} · ${t.who}</span></span>
          <span class="qpri" style="color:${PRI[t.pri]};border-color:${PRI[t.pri]}">${t.pri}</span>
          <span class="qage">${mode==='age' ? ageFmt(t.age) : fmt(t.sla)}</span>
        </div>`;
      }).join('');
    } else {
      // same order — patch values in place so nothing re-animates
      rows.forEach(t=>{
        const row = el.querySelector(`[data-id="${t.id}"]`);
        if(!row) return;
        const s = state(t);
        row.className = 'qrow ' + s.cls;
        const arc = row.querySelector('.qarc');
        arc.setAttribute('stroke-dashoffset', s.dash);
        arc.setAttribute('stroke', s.col);
        const lab = row.querySelector('.qring b');
        lab.textContent = s.label; lab.style.color = s.col;
        row.querySelector('.qage').textContent = mode==='age' ? ageFmt(t.age) : fmt(t.sla);
      });
    }

    const outage = rows.findIndex(t=>t.id==='INC-4821') + 1;
    const v = document.getElementById('q-verdict');
    v.innerHTML = mode === 'age'
      ? `<strong style="color:var(--warn)">The outage is row ${outage} of 6.</strong> Fourteen people can't work, nine minutes of SLA left — and it's below a laptop request that's been sitting for seven hours. An agent has to read the whole list and do the maths themselves, on every refresh.`
      : `<strong style="color:var(--ok)">The outage is row ${outage}.</strong> Same six tickets, same data, one ordering change. The first row is always the next thing to work on — and a new joiner performs like a senior agent on day one, because the judgement is in the system rather than in someone's head.`;
  }

  function tick(){
    TICKETS.forEach(t=>{ if(t.sla > -5) t.sla -= 1; t.age += 1; });
    render();
  }

  document.querySelectorAll('[data-q]').forEach(b=>{
    b.addEventListener('click', ()=>{
      document.querySelectorAll('[data-q]').forEach(x=>x.setAttribute('aria-pressed','false'));
      b.setAttribute('aria-pressed','true');
      mode = b.dataset.q;
      render();
    });
  });

  render();
  if(!REDUCED()){
    timer = setInterval(tick, 2000);
    TIMERS.push(timer);
  }
}

