/* ---------- Connection flow ---------- */
function initConnect(){
  const stage = document.getElementById('cx-stage');
  if(!stage) return;

  const STEPS = [
    {n:'Domain ownership',    d:'sales.company.com',        s:'verified'},
    {n:'SPF record',          d:'v=spf1 include:_sc.io ~all', s:'published'},
    {n:'DKIM record',         d:'sc._domainkey · 2048-bit',  s:'signed'},
    {n:'DMARC policy',        d:'p=quarantine; rua=…',       s:'enforced'},
    {n:'MX records',          d:'Priority 10, 20 · resolving', s:'resolving'},
    {n:'Mailbox provisioned', d:'Google Workspace · 3 seats', s:'connected'},
    {n:'Test send',           d:'Delivered to inbox in 1.4s', s:'inbox'}
  ];
  const STEP_MS = 620;
  let mode = 'v2', running = false;

  function renderIdle(){
    if(mode === 'v2'){
      stage.innerHTML = `<div class="cx-steps">${STEPS.map(s=>`
        <div class="cx-s"><span class="cx-ic">○</span>
          <span class="cx-nm"><b>${s.n}</b><span>${s.d}</span></span>
          <span class="cx-st">waiting</span></div>`).join('')}</div>`;
    } else {
      stage.innerHTML = `<div class="cx-spin">
        <div class="cx-spin-ring" style="animation:none;border-top-color:var(--t4)"></div>
        <p>Ready to set up your domain</p>
        <small>You'll see a progress indicator while we work.</small>
      </div>`;
    }
    document.getElementById('cx-clock').textContent = '';
  }

  function finishCopy(){
    const v = document.getElementById('cx-verdict');
    v.innerHTML = mode === 'v2'
      ? `<strong style="color:var(--ok)">Done — and you can audit it.</strong> Seven named checks, each independently verified. If DMARC had failed you'd know which record and why, without a support ticket. This is the version that shipped.`
      : `<strong style="color:var(--warn)">Done — but what actually happened?</strong> Same duration, same result, zero ability to verify it. For a user who is <em>afraid of permanently damaging their domain</em>, this is the worst possible interface. This is the version I nearly built.`;
  }

  function run(){
    if(running) return;
    running = true;
    clearTimers();
    const btn = document.getElementById('cx-run');
    btn.disabled = true;
    const total = STEPS.length * STEP_MS;
    const t0 = Date.now();
    const clock = document.getElementById('cx-clock');
    const tick = setInterval(()=>{
      clock.textContent = `${((Date.now()-t0)/1000).toFixed(1)}s elapsed`;
    }, 100);
    TIMERS.push(tick);

    if(mode === 'v1'){
      stage.innerHTML = `<div class="cx-spin">
        <div class="cx-spin-ring"></div>
        <p>Setting up your domain…</p>
        <small>This usually takes a moment. Please don't close this window.</small>
      </div>`;
      later(()=>{
        clearInterval(tick);
        stage.innerHTML = `<div class="cx-spin done">
          <div class="cx-spin-ring" style="border-color:var(--ok)"></div>
          <p style="color:var(--ok)">Setup complete</p>
          <small>Your domain is ready to send.</small>
        </div>`;
        clock.textContent = `${(total/1000).toFixed(1)}s elapsed`;
        finishCopy(); btn.disabled = false; running = false;
      }, REDUCED() ? 300 : total);
      return;
    }

    renderIdle();
    const rows = [...stage.querySelectorAll('.cx-s')];
    if(REDUCED()){
      rows.forEach((r,i)=>{ r.className='cx-s done'; r.querySelector('.cx-ic').textContent='✓'; r.querySelector('.cx-st').textContent=STEPS[i].s; });
      clearInterval(tick); clock.textContent = `${(total/1000).toFixed(1)}s elapsed`;
      finishCopy(); btn.disabled=false; running=false; return;
    }
    rows.forEach((row,i)=>{
      later(()=>{
        row.classList.add('active');
        row.querySelector('.cx-st').textContent = 'checking…';
      }, i*STEP_MS);
      later(()=>{
        row.classList.remove('active'); row.classList.add('done');
        row.querySelector('.cx-ic').textContent = '✓';
        row.querySelector('.cx-st').textContent = STEPS[i].s;
        if(i === rows.length-1){
          clearInterval(tick);
          clock.textContent = `${(total/1000).toFixed(1)}s elapsed`;
          finishCopy(); btn.disabled = false; running = false;
        }
      }, i*STEP_MS + STEP_MS*0.82);
    });
  }

  document.querySelectorAll('[data-cx]').forEach(b=>{
    b.addEventListener('click', ()=>{
      if(running) return;
      document.querySelectorAll('[data-cx]').forEach(x=>x.setAttribute('aria-pressed','false'));
      b.setAttribute('aria-pressed','true');
      mode = b.dataset.cx;
      clearTimers(); renderIdle();
      document.getElementById('cx-verdict').innerHTML = mode==='v2'
        ? `The version that shipped. Every record is named and independently verified — press connect and watch what you can actually confirm.`
        : `The version I nearly built. Identical duration, identical outcome. Press connect and notice what you <em>can't</em> confirm at the end.`;
    });
  });
  document.getElementById('cx-run').addEventListener('click', run);
  renderIdle();
}

/* ---------- Reputation over time ---------- */
function initReputation(){
  const svgLine = document.getElementById('rep-g-line');
  if(!svgLine) return;

  const W = 620, H = 210, PAD_T = 14, PAD_B = 24, DAYS = 30;
  const SERIES = [
    {id:'rep-g', line:'rep-g-line', lo:62, hi:96},
    {id:'rep-o', line:'rep-o-line', lo:58, hi:92},
    {id:'rep-y', line:'rep-y-line', lo:55, hi:89}
  ];
  const ease = t => 1 - Math.pow(1 - t, 2.4);
  const val = (s,i) => {
    const t = i/(DAYS-1);
    const shaped = t < 0.17 ? t*0.55 : ease((t-0.17)/0.83)*0.93 + 0.094;
    return s.lo + (s.hi - s.lo) * Math.min(1, shaped);
  };
  const y = v => PAD_T + (H - PAD_T - PAD_B) * (1 - (v-45)/(100-45));
  const x = i => (i/(DAYS-1)) * W;

  SERIES.forEach(s=>{
    const pts = Array.from({length:DAYS},(_,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(val(s,i)).toFixed(1)}`).join(' ');
    const el = document.getElementById(s.line);
    el.setAttribute('d', pts);
    s.el = el; s.len = el.getTotalLength();
  });
  const g = SERIES[0];
  const area = document.getElementById('rep-area');
  area.setAttribute('d', g.el.getAttribute('d') + ` L${W} ${H-PAD_B} L0 ${H-PAD_B} Z`);
  const head = document.getElementById('rep-head');

  function setFinal(){
    SERIES.forEach(s=>{ s.el.style.strokeDasharray='none'; s.el.style.strokeDashoffset='0';
      document.getElementById(s.id).textContent = Math.round(s.hi)+'%'; });
    area.style.opacity = 1;
    const p = g.el.getPointAtLength(g.len);
    head.setAttribute('cx',p.x); head.setAttribute('cy',p.y); head.style.opacity=1;
    document.getElementById('rep-day').textContent = 'Day 30';
  }

  let raf = null;
  function play(){
    if(raf) cancelAnimationFrame(raf);
    if(REDUCED()){ setFinal(); return; }
    const DUR = 2600, t0 = performance.now();
    SERIES.forEach(s=>{ s.el.style.transition='none'; s.el.style.strokeDasharray=s.len; s.el.style.strokeDashoffset=s.len; });
    area.style.opacity = 0; head.style.opacity = 0;

    const frame = now => {
      const t = Math.min(1, (now - t0)/DUR);
      SERIES.forEach(s=>{
        s.el.style.strokeDashoffset = s.len * (1-t);
        const idx = t*(DAYS-1);
        document.getElementById(s.id).textContent = Math.round(val(s, Math.min(DAYS-1, idx)))+'%';
      });
      area.style.opacity = t*0.9;
      const p = g.el.getPointAtLength(g.len * t);
      head.setAttribute('cx',p.x); head.setAttribute('cy',p.y); head.style.opacity = 1;
      document.getElementById('rep-day').textContent = 'Day ' + Math.max(1, Math.round(t*DAYS));
      if(t < 1) raf = requestAnimationFrame(frame); else { raf = null; setFinal(); }
    };
    raf = requestAnimationFrame(frame);
  }

  document.getElementById('rep-play').addEventListener('click', play);

  // play once when scrolled into view
  const io = new IntersectionObserver(es=>{
    es.forEach(e=>{ if(e.isIntersecting){ play(); io.disconnect(); } });
  }, {threshold:.35});
  io.observe(document.getElementById('demo-rep'));
  setFinal();
}

/* ---------- Campaign execution ---------- */
function initCampaign(){
  const seqEl = document.getElementById('cmp-seq');
  if(!seqEl) return;

  const STEPS = [
    {n:'Step 1 — Intro',     s:'Sent to all active leads', target:1250},
    {n:'Wait 3 days',        s:'Reply detection running',  target:0},
    {n:'Step 2 — Follow-up', s:'Skips anyone who replied', target:1109},
    {n:'Wait 4 days',        s:'Reply detection running',  target:0},
    {n:'Step 3 — Break-up',  s:'Skips anyone who replied', target:1024}
  ];
  const BOXES = [
    {n:'sales@',  cap:150, health:98},
    {n:'team@',   cap:140, health:95},
    {n:'info@',   cap:120, health:97}
  ];
  let running = false, sent = 0, replies = 0, meetings = 0, removed = 0;

  const stats = () => `
    ${[['cmp-sent',sent.toLocaleString(),'emails sent','var(--fg)'],
       ['cmp-rep',replies.toLocaleString(),'replies detected','var(--ok)'],
       ['cmp-rm',removed.toLocaleString(),'removed from sequence','var(--warn)'],
       ['cmp-mt',meetings.toLocaleString(),'meetings booked','var(--ac)']]
      .map(([id,v,l,c])=>`<div class="cmp-st"><b id="${id}" style="color:${c}">${v}</b><span>${l}</span></div>`).join('')}`;

  function renderSeq(active=-1, doneTo=-1){
    seqEl.innerHTML = STEPS.map((s,i)=>{
      const finished = i <= doneTo;
      const shown = finished ? s.target : 0;
      return `
      <div class="cmp-step${i===active?' active':''}${finished?' done':''}">
        <span class="lbl">${i%2 ? 'Delay' : 'Email'}</span>
        <b>${s.n}</b><span class="sub">${s.s}</span>
        ${s.target
          ? `<em id="cmp-t${i}">${shown.toLocaleString()} / ${s.target.toLocaleString()}</em>`
          : `<em>${finished ? 'Complete' : '&nbsp;'}</em>`}
        <span class="cmp-step-bar" id="cmp-b${i}"></span>
      </div>`;
    }).join('');
  }
  function renderBoxes(prog=0){
    document.getElementById('cmp-boxes').innerHTML = BOXES.map((b,i)=>{
      const cur = Math.round(b.cap * prog);
      return `<div class="comp-r">
        <span class="nm">${b.n}</span>
        <span class="comp-tr"><span class="comp-f" style="width:${(cur/b.cap)*100}%;background:var(--ac)"></span></span>
        <span class="vl">${cur}/${b.cap}</span>
      </div>`;
    }).join('');
  }
  function feed(html, colour){
    const f = document.getElementById('cmp-feed');
    const d = document.createElement('div');
    d.className = 'cmp-ev';
    d.innerHTML = `<i style="background:${colour}"></i><span>${html}</span><em>now</em>`;
    f.prepend(d);
    while(f.children.length > 9) f.lastChild.remove();
  }
  function setState(txt, cls){
    const el = document.getElementById('cmp-state');
    el.textContent = txt; el.className = 'cmp-state' + (cls?' '+cls:'');
  }
  function reset(){
    clearTimers();
    running = false; sent = replies = meetings = removed = 0;
    renderSeq(); renderBoxes(0);
    document.getElementById('cmp-stats').innerHTML = stats();
    document.getElementById('cmp-feed').innerHTML = '';
    setState('Ready',''); document.getElementById('cmp-run').disabled = false;
  }

  function run(){
    if(running) return;
    running = true;
    clearTimers();
    document.getElementById('cmp-run').disabled = true;
    setState('Running','running');
    sent = replies = meetings = removed = 0;
    document.getElementById('cmp-feed').innerHTML = '';

    if(REDUCED()){
      sent = 3383; replies = 226; removed = 226; meetings = 34;
      renderSeq(-1, STEPS.length-1); renderBoxes(1);
      document.getElementById('cmp-stats').innerHTML = stats();
      feed('Campaign complete — <b>226 replies</b>, 34 meetings booked', 'var(--ok)');
      setState('Complete','done'); document.getElementById('cmp-run').disabled = false; running = false;
      return;
    }

    let clock = 0;
    STEPS.forEach((s,i)=>{
      const dur = s.target ? 2000 : 1100;
      const start = clock; clock += dur + 220;

      later(()=>{
        renderSeq(i, i-1);
        renderBoxes(0);
        if(s.target){
          feed(`<b>${s.n}</b> dispatching to ${s.target.toLocaleString()} leads`, 'var(--ac)');
          const t0 = performance.now();
          const step = now => {
            const t = Math.min(1, (now-t0)/dur);
            const n = Math.round(s.target * t);
            const el = document.getElementById('cmp-t'+i);
            if(el) el.textContent = `${n.toLocaleString()} / ${s.target.toLocaleString()}`;
            const bar = document.getElementById('cmp-b'+i);
            if(bar) bar.style.width = (t*100)+'%';
            renderBoxes(t);
            document.getElementById('cmp-sent').textContent = (sent + n).toLocaleString();
            if(t<1) requestAnimationFrame(step);
            else { sent += s.target; }
          };
          requestAnimationFrame(step);
        } else {
          feed(`<b>${s.n}</b> — monitoring inboxes for replies`, 'var(--fg-3)');
          const batch = i===1 ? 141 : 85;
          const mtg   = i===1 ? 19 : 15;
          for(let k=0;k<5;k++){
            later(()=>{
              const add = Math.round(batch/5), addM = Math.round(mtg/5);
              replies += add; removed += add; meetings += addM;
              document.getElementById('cmp-rep').textContent = replies.toLocaleString();
              document.getElementById('cmp-rm').textContent = removed.toLocaleString();
              document.getElementById('cmp-mt').textContent = meetings.toLocaleString();
              if(k===2) feed(`<b>${add*3} replies</b> detected — those leads removed from all remaining steps`, 'var(--ok)');
            }, (k+1)*(dur/5));
          }
        }
      }, start);
    });

    later(()=>{
      renderSeq(-1, STEPS.length-1);
      feed(`Campaign complete — <b>${replies} replies</b>, ${meetings} meetings booked, ${removed} leads protected from over-sending`, 'var(--ok)');
      setState('Complete','done');
      document.getElementById('cmp-run').disabled = false;
      running = false;
    }, clock + 200);
  }

  document.getElementById('cmp-run').addEventListener('click', run);
  document.getElementById('cmp-reset').addEventListener('click', reset);
  reset();
}

/* ---------- Warm-up ramp ---------- */
function initWarmup(){
  const ramp = document.getElementById('ramp');
  if(!ramp) return;
  let duration = 30;
  const TARGET = 150;

  function render(){
    const today = Math.max(1, Math.round(duration * 0.4));
    let html = '';
    for(let d=1; d<=duration; d++){
      const v = Math.round(10 + (TARGET-10) * Math.pow(d/duration, 1.9));
      const h = (v/TARGET)*100;
      html += `<div class="ramp-b${d>today?' fut':''}" style="height:${h}%" title="Day ${d}: ${v}/day"></div>`;
    }
    ramp.innerHTML = html;

    const todayVol = Math.round(10 + (TARGET-10) * Math.pow(today/duration, 1.9));
    document.getElementById('wu-day').textContent = `Day ${today}`;
    document.getElementById('ramp-mid').textContent = `Day ${Math.round(duration/2)}`;
    document.getElementById('ramp-end').textContent = `Day ${duration}`;
    document.getElementById('wu-vol').textContent = `${todayVol}/day`;
    document.getElementById('wu-vol-f').style.width = `${(todayVol/TARGET)*100}%`;
    document.getElementById('wu-msg').innerHTML =
      `On track. Full sending volume available in <strong>${duration-today} days</strong>.`;

    // reputation improves with elapsed ramp
    const prog = today/duration;
    const rep = {'wu-g':[62,96],'wu-o':[58,92],'wu-y':[55,89]};
    Object.entries(rep).forEach(([id,[lo,hi]])=>{
      const v = Math.round(lo + (hi-lo)*prog);
      document.getElementById(id+'-f').style.width = v+'%';
      document.getElementById(id+'-v').textContent = v+'%';
    });
  }

  document.querySelectorAll('[data-wu]').forEach(b=>{
    b.addEventListener('click', ()=>{
      document.querySelectorAll('[data-wu]').forEach(x=>x.setAttribute('aria-pressed','false'));
      b.setAttribute('aria-pressed','true');
      duration = +b.dataset.wu;
      render();
    });
  });

  render();
}

